    pass


class Conflict(RuntimeError):
    pass
"""Secondary indexes. Each index maps a key to the set of record ids."""
from collections import defaultdict

from libcat.util.dates import years_of


class _SetIndex:
    def __init__(self):
        self._buckets = defaultdict(set)

    def _keys(self, record):
        raise NotImplementedError

    def add(self, record):
        for key in self._keys(record):
            self._buckets[key].add(record.id)

    def remove(self, record):
        for key in self._keys(record):
            bucket = self._buckets.get(key)
            if bucket is not None:
                bucket.discard(record.id)
                if not bucket:
                    del self._buckets[key]

    def ids_for(self, key):
        return set(self._buckets.get(key, ()))

    def counts(self):
        return {k: len(v) for k, v in self._buckets.items()}

    def buckets(self):
        return {k: set(v) for k, v in self._buckets.items()}


class YearIndex(_SetIndex):
    def _keys(self, record):
        return years_of(record.date)

    def ids_between(self, year_from=None, year_to=None):
        out = set()
        for year, ids in self._buckets.items():
            if year_from is not None and year < year_from:
                continue
            if year_to is not None and year > year_to:
                continue
            out |= ids
        return out


class SubjectIndex(_SetIndex):
    def _keys(self, record):
        return set(record.subjects)
import datetime as dt
import unittest

from libcat.util.dates import display_year, parse_date, years_of


class DatesTest(unittest.TestCase):
    def test_parse_partial_dates(self):
        self.assertEqual(parse_date("2019"), dt.date(2019, 1, 1))
        self.assertEqual(parse_date("2019-05"), dt.date(2019, 5, 1))
        self.assertEqual(parse_date("2019.05.17"), dt.date(2019, 5, 17))
        self.assertIsNone(parse_date("2019-13-01"))
        self.assertIsNone(parse_date("spring 2019"))

    def test_years_of(self):
        self.assertEqual(years_of("2019-05-01"), {2019})
        self.assertEqual(years_of("1998"), {1998})
        self.assertEqual(years_of("c. 1900"), set())
        self.assertEqual(years_of(None), set())
        self.assertEqual(years_of(""), set())

    def test_display_year(self):
        self.assertEqual(display_year("2021-01"), "2021")
        self.assertEqual(display_year(None), "n.d.")

